{
  "county_id": "HVA91",
  "actions": [
    {
      "action_id": "timed-pathways",
      "action": "Proposed: Adopt national cancer-specific pathways with maximum times per step and a single fast-track referral from primary care, following the Danish and Swedish model.",
      "rationale": "The portfolio picked timed-pathways for Åland at EUR 46,254 a year, with a model scenario of 1.4 deaths postponed per year (range 0.2-2.8) and it stayed in 94% of sensitivity runs.",
      "owner_role": "Accountable owner: Wellbeing services county, coordinated nationally by FICAN.",
      "indicator": "Indicator to monitor: Patients waiting over 6 months during the year for access to specialised health care per 10 000 inhabitants.",
      "roadmap_measure": "3.1.2"
    },
    {
      "action_id": "pathway-timestamps",
      "action": "Proposed: Add first contact, referral, diagnosis and first treatment dates, plus entry route, to the national cancer quality register and publish county-level medians quarterly.",
      "rationale": "This is the first step for every county, and Åland cannot check the Goal 3 indicator because time from referral to diagnosis and from diagnosis to first treatment is not published by county for any cancer.",
      "owner_role": "Accountable owner: FICAN with THL and the Finnish Cancer Registry.",
      "indicator": "Indicator to monitor: Share of new cancer cases with all four timestamps recorded.",
      "roadmap_measure": "3.2.1"
    },
    {
      "action_id": "equal-fast-lane",
      "action": "Proposed: Same-week physician assessment and direct-access diagnostics for red-flag symptoms in public health centres, regardless of employment or insurance.",
      "rationale": "Åland's age-standardised cancer mortality ratio was 1.024 (95% interval 0.958-1.093), about 1.9 more deaths a year than its age structure predicts, and the public route in the Finnish DLBCL cohort took a mean 207 days from symptom to treatment against 123 days through private or occupational care.",
      "owner_role": "Accountable owner: Wellbeing services county primary care.",
      "indicator": "Indicator to monitor: Waiting time for elective outpatient medical visit (physician) in primary health care exceeds 7 days from assessment of the need for treatment, % appointments kept.",
      "roadmap_measure": "2.5.2"
    }
  ],
  "evidence_does_not_support": "timed-pathways: Danish evidence is before/after without a control group. Patients left outside the pathway waited 4 days longer, so coverage must be monitored."
}

